insert into public.lesson_slides (lesson_id, position, kind, payload)
select l.id, v.pos, v.kind, v.payload::jsonb
from (values
  ('hsk0-01-how-to-study', 1, 'fact', '{"emoji":"🎯","title":"Зачем нужен HSK 0","text":"HSK — это международный экзамен по китайскому языку (уровни 1–6). Но прежде чем учить слова, важно поставить произношение, научиться читать пиньинь и понять логику иероглифов. Именно этому посвящён HSK 0."}'),
  ('hsk0-01-how-to-study', 2, 'theory', '{"title":"Как проходить уроки с максимальной пользой","blocks":[{"t":"table","head":["Правило","Зачем это нужно"],"rows":[["1. Заведите тетрадь в клетку","Выписывайте правила, таблицы и прописывайте каждую черту и ключ рукой — так включается моторная память."],["2. Слушайте и повторяйте вслух","Нажимайте на кнопку звука рядом с каждым примером и повторяйте за диктором."],["3. Не спешите учить слова","На уровне HSK 0 ваша главная цель — не «плавать» в пиньине, тонах и ключах."],["4. Делайте короткие подходы","15–20 минут каждый день дают в разы больше, чем два часа раз в неделю."]]},{"t":"tip","text":"Подготовьте ручку и блокнот прямо сейчас — впереди таблицы и первые черты!"}]}'),
  ('hsk0-01-how-to-study', 3, 'quiz', '{"title":"Проверим настрой","qs":[{"q":"Какая главная цель курса HSK 0?","options":["Научиться читать пиньинь, различать тоны и понимать ключи","Выучить 500 сложных слов","Сдать экзамен HSK 4"],"correct":0},{"q":"Во время прохождения HSK 0 полезно вести конспект и прописывать черты в тетради.","tf":true},{"q":"Озвучку в примерах можно не слушать, китайский читается так же, как английский.","tf":false,"explain":"В пиньине многие латинские буквы читаются совсем не так, как в английском."},{"q":"Сколько уровней в классическом стандарте HSK 2.0?","options":["6 уровней (HSK 1–6)","2 уровня","12 уровней"],"correct":0},{"q":"Какой режим занятий самый эффективный?","options":["15–20 минут каждый день","Раз в месяц по 3 часа","Только читать теорию без упражнений"],"correct":0}]}'),
  ('hsk0-02-chinese-language', 1, 'fact', '{"emoji":"🌏","title":"Один язык — миллиард собеседников","text":"В Китае много диалектов (например, кантонский или шанхайский), но общий государственный язык для всей страны — путунхуа 普通话 pǔtōnghuà («общеупотребительная речь»)."}'),
  ('hsk0-02-chinese-language', 2, 'theory', '{"title":"Три опоры китайского языка","blocks":[{"t":"table","head":["Элемент","Что это","Пример"],"rows":[["Пиньинь","Запись звучания латинскими буквами","nǐ hǎo"],["Тон","Высота и мелодия голоса на слоге","mā (1-й), mǎ (3-й)"],["Иероглиф","Знак письма, несущий смысл","你好 nǐ hǎo"]]},{"t":"ex","zh":"普通话","py":"pǔtōnghuà","m":"общий китайский язык"},{"t":"ex","zh":"汉语","py":"Hànyǔ","m":"китайский язык"},{"t":"tip","text":"В материковом Китае используют упрощённые иероглифы — именно их мы и изучаем."}]}'),
  ('hsk0-02-chinese-language', 3, 'game', '{"type":"match","title":"Соедините понятия","pairs":[["普通话 pǔtōnghuà","общий китайский язык"],["汉语 Hànyǔ","китайский язык"],["пиньинь","запись звуков латиницей"],["тон","мелодия голоса на слоге"],["иероглиф","знак письма со смыслом"]]}'),
  ('hsk0-02-chinese-language', 4, 'quiz', '{"title":"Проверим","qs":[{"q":"Как называется общий государственный язык Китая?","options":["Путунхуа 普通话 pǔtōnghuà","Кантонский","Пиньинь"],"correct":0},{"q":"Что такое пиньинь?","options":["Система записи звучания слогов латинскими буквами","Название диалекта","Вид иероглифов"],"correct":0},{"q":"В этом курсе мы изучаем упрощённые иероглифы.","tf":true},{"q":"Что означает 汉语 Hànyǔ?","options":["китайский язык","экзамен","иероглиф"],"correct":0},{"q":"Путунхуа понимают только в Пекине.","tf":false,"explain":"Путунхуа — общий язык для всего Китая."}]}'),
  ('hsk0-03-writing-system', 1, 'fact', '{"emoji":"📜","title":"Письменности больше 3000 лет","text":"Древние китайские знаки были рисунками предметов. Со временем линии выпрямились, чтобы их было удобно писать кистью, но в простых знаках до сих пор угадывается картинка."}'),
  ('hsk0-03-writing-system', 2, 'theory', '{"title":"Эволюция простых знаков","blocks":[{"t":"table","head":["Иероглиф","Пиньинь","Что изображает","Ассоциация"],"rows":[["日","rì","солнце, день","Окошко с перекладиной — диск солнца"],["月","yuè","луна, месяц","Полумесяц с двумя полосками внутри"],["山","shān","гора","Три горные вершины (высокая в центре)"],["水","shuǐ","вода","Поток воды в центре и брызги по бокам"],["火","huǒ","огонь","Языки пламени и искры"],["人","rén","человек","Шагающий человек (вид сбоку)"]]},{"t":"chart","cols":6,"cells":[["日 rì","日"],["月 yuè","月"],["山 shān","山"],["水 shuǐ","水"],["火 huǒ","火"],["人 rén","人"]]},{"t":"tip","text":"Нажимайте на карточки в таблице выше, чтобы послушать произношение каждого знака."}]}'),
  ('hsk0-03-writing-system', 3, 'game', '{"type":"match","title":"Найдите значение знака","pairs":[["日 rì","солнце, день"],["月 yuè","луна, месяц"],["山 shān","гора"],["水 shuǐ","вода"],["火 huǒ","огонь"],["人 rén","человек"]]}'),
  ('hsk0-03-writing-system', 4, 'game', '{"type":"listen","title":"Послушайте и выберите знак","items":[{"say":"日","options":["日 rì","月 yuè","山 shān","水 shuǐ"],"correct":0},{"say":"月","options":["日 rì","月 yuè","火 huǒ","人 rén"],"correct":1},{"say":"山","options":["水 shuǐ","山 shān","火 huǒ","日 rì"],"correct":1},{"say":"水","options":["人 rén","月 yuè","水 shuǐ","山 shān"],"correct":2},{"say":"火","options":["火 huǒ","日 rì","人 rén","月 yuè"],"correct":0},{"say":"人","options":["山 shān","水 shuǐ","火 huǒ","人 rén"],"correct":3}]}'),
  ('hsk0-03-writing-system', 5, 'quiz', '{"title":"Закрепим","qs":[{"q":"Какой иероглиф похож на три горные вершины?","options":["山 shān","水 shuǐ","火 huǒ"],"correct":0},{"q":"Что означает знак 日 rì?","options":["солнце, день","луна, месяц","вода"],"correct":0},{"q":"Что означает знак 月 yuè?","options":["луна, месяц","огонь","человек"],"correct":0},{"q":"В китайском языке нет алфавита: один иероглиф обычно равен одному слогу.","tf":true},{"q":"Какой знак изображает шагающего человека?","options":["人 rén","火 huǒ","山 shān"],"correct":0}]}'),
  ('hsk0-04-syllable-structure', 1, 'fact', '{"emoji":"🧩","title":"Конструктор из 400 деталей","text":"В русском языке тысячи разных слогов, а в китайском — всего около 400 (без учёта тонов). Каждый слог собирается по строгой формуле."}'),
  ('hsk0-04-syllable-structure', 2, 'theory', '{"title":"Формула слога: Инициаль + Финаль + Тон","blocks":[{"t":"table","head":["Слог","Инициаль (начало)","Финаль (конец)","Тон"],"rows":[["mā","m","a","1-й (ˉ)"],["hǎo","h","ao","3-й (ˇ)"],["shuǐ","sh","ui","3-й (ˇ)"],["dà","d","a","4-й (ˋ)"],["ài","нет","ai","4-й (ˋ)"]]},{"t":"tip","text":"Инициаль — это начальный согласный (её может не быть). Финаль — гласная часть слога. Тон — обязательная мелодия слога."}]}'),
  ('hsk0-04-syllable-structure', 3, 'game', '{"type":"build","title":"Разберите слог на части","items":[{"target":"妈 mā","answer":["m","ā"],"hint":"Соберите слог mā: инициаль + финаль"},{"target":"好 hǎo","answer":["h","ǎo"],"hint":"Соберите слог hǎo: инициаль + финаль"},{"target":"大 dà","answer":["d","à"],"hint":"Соберите слог dà: инициаль + финаль"},{"target":"水 shuǐ","answer":["sh","uǐ"],"hint":"Соберите слог shuǐ: инициаль + финаль"},{"target":"他 tā","answer":["t","ā"],"hint":"Соберите слог tā: инициаль + финаль"},{"target":"你 nǐ","answer":["n","ǐ"],"hint":"Соберите слог nǐ: инициаль + финаль"}]}'),
  ('hsk0-04-syllable-structure', 4, 'quiz', '{"title":"Проверим","qs":[{"q":"Из каких частей состоит китайский слог?","options":["Инициаль + финаль + тон","Только согласные","Две инициали"],"correct":0},{"q":"Какая инициаль в слоге hǎo?","options":["h","ao","o"],"correct":0},{"q":"Какая финаль в слоге mā?","options":["a","m","ma"],"correct":0},{"q":"Слог может состоять только из финали и тона, без инициали (например, ài).","tf":true},{"q":"Сколько примерно слогов в китайском языке без учёта тонов?","options":["Около 400","Около 50","Около 10 000"],"correct":0},{"q":"Какая инициаль в слоге shuǐ?","options":["sh","s","uǐ"],"correct":0}]}'),
  ('hsk0-05-trick-letters', 1, 'fact', '{"emoji":"⚠️","title":"Не читайте пиньинь по-английски!","text":"Главная ловушка новичков — читать латинские буквы пиньиня по правилам английского языка. В пиньине у многих букв совсем другие звуки."}'),
  ('hsk0-05-trick-letters', 2, 'theory', '{"title":"Таблица букв-обманок (сохраните в конспект!)","blocks":[{"t":"table","head":["Буква","Неправильно","Как звучит на самом деле","Пример"],"rows":[["q","«к»","Мягкое «чь» с сильным выдохом","七 qī (семь)"],["x","«кс»","Мягкое «сь» (как в «сито»)","西 xī (запад)"],["c","«к» или «с»","Твёрдое «ц» с сильным выдохом","三 sān / 次 cì"],["zh","«зх»","Твёрдое «чж» (язык загнут назад)","这 zhè (это)"],["e","«е»","Глубокое «э/ы» (губы растянуты)","鹅 é (гусь)"],["ü","«у»","«Юй» (губы трубочкой, язык как на «и»)","鱼 yú / 女 nǚ"]]},{"t":"chart","cols":6,"cells":[["qī","七"],["xī","西"],["cì","次"],["zhè","这"],["é","鹅"],["nǚ","女"]]},{"t":"tip","text":"Мы подробно отработаем каждый из этих звуков в следующих разделах. Сейчас важно просто запомнить, что пиньинь — это фонетический код, а не английский текст."}]}'),
  ('hsk0-05-trick-letters', 3, 'game', '{"type":"match","title":"Найдите правильное звучание","pairs":[["q (七 qī)","мягкое «чь» с выдохом"],["x (西 xī)","мягкое «сь»"],["c (次 cì)","«ц» с сильным выдохом"],["zh (这 zhè)","твёрдое «чж»"],["ü (女 nǚ)","«и» с губами трубочкой"]]}'),
  ('hsk0-05-trick-letters', 4, 'game', '{"type":"listen","title":"Послушайте буквы-обманки","items":[{"say":"七","options":["qī","xī","cì","zhè"],"correct":0},{"say":"西","options":["qī","xī","cì","é"],"correct":1},{"say":"次","options":["xī","cì","zhè","nǚ"],"correct":1},{"say":"这","options":["qī","cì","zhè","xī"],"correct":2},{"say":"女","options":["é","nǚ","qī","xī"],"correct":1}]}'),
  ('hsk0-05-trick-letters', 5, 'quiz', '{"title":"Проверим","qs":[{"q":"Как читается буква q в пиньине (например, 七 qī)?","options":["Мягкое «чь» с выдохом","Как «к»","Как «кв»"],"correct":0},{"q":"Как читается буква x в пиньине (например, 西 xī)?","options":["Мягкое «сь»","Как «кс»","Как «х»"],"correct":0},{"q":"Как читается буква c в пиньине (например, 次 cì)?","options":["«Ц» с выдохом","Как «к»","Как «с»"],"correct":0},{"q":"Буква zh читается как твёрдое «чж» с загнутым к нёбу языком.","tf":true},{"q":"Как произнести гласную ü (女 nǚ)?","options":["Сказать «и» и вытянуть губы трубочкой","Как обычное «у»","Как «а»"],"correct":0}]}'),
  ('hsk0-06-simple-vowels', 1, 'fact', '{"emoji":"🦷","title":"Всего шесть базовых гласных","text":"Вся система гласных пиньиня строится всего из шести букв: a, o, e, i, u, ü. Освоив их чистую артикуляцию, вы легко прочитаете любую комбинацию."}'),
  ('hsk0-06-simple-vowels', 2, 'theory', '{"title":"Артикуляция шести гласных","blocks":[{"t":"chart","cols":6,"cells":[["a","啊"],["o","哦"],["e","鹅"],["i","衣"],["u","乌"],["ü","鱼"]]},{"t":"table","head":["Гласная","Положение губ и языка","Пример"],"rows":[["a","Рот широко открыт, как у врача «а-а-а»","啊 ā"],["o","Губы округлены, звук глубокий «о»","哦 ó"],["e","Губы растянуты в полуулыбке, язык оттянут назад («э/ы»)","鹅 é"],["i","Губы растянуты, язык у передних зубов («и»)","衣 yī"],["u","Губы сильно вытянуты трубочкой («у»)","乌 wū"],["ü","Язык как на «i», а губы трубочкой как на «u»","鱼 yú"]]},{"t":"tip","text":"Самая частая ошибка — путать o и e. На o губы круглые, на e губы растянуты в стороны!"}]}'),
  ('hsk0-06-simple-vowels', 3, 'game', '{"type":"listen","title":"Послушайте и выберите гласную","items":[{"say":"啊","options":["a","o","e","i"],"correct":0},{"say":"哦","options":["a","o","e","u"],"correct":1},{"say":"鹅","options":["a","o","e","i"],"correct":2},{"say":"衣","options":["i","u","ü","e"],"correct":0},{"say":"乌","options":["i","u","ü","o"],"correct":1},{"say":"鱼","options":["i","u","ü","e"],"correct":2},{"say":"鹅","options":["o","e"],"correct":1},{"say":"鱼","options":["u","ü"],"correct":1}]}'),
  ('hsk0-06-simple-vowels', 4, 'game', '{"type":"match","title":"Соедините звук и артикуляцию","pairs":[["a (啊 ā)","рот широко открыт"],["o (哦 ó)","губы округлены"],["e (鹅 é)","губы растянуты, язык назад"],["u (乌 wū)","губы трубочкой, язык назад"],["ü (鱼 yú)","губы трубочкой, язык вперёд"]]}'),
  ('hsk0-06-simple-vowels', 5, 'quiz', '{"title":"Проверим","qs":[{"q":"При какой гласной губы растянуты в стороны, а язык оттянут назад?","options":["e","o","u"],"correct":0},{"q":"Как правильно произнести ü?","options":["Язык как на «и», губы трубочкой как на «у»","Рот широко открыт","Как обычное «у»"],"correct":0},{"q":"При какой гласной губы округлены?","options":["o","e","i"],"correct":0},{"q":"В пиньине шесть базовых простых гласных: a, o, e, i, u, ü.","tf":true},{"q":"Какой звук слышится в слоге 鹅 é?","options":["e","o","a"],"correct":0},{"q":"Какой звук слышится в слоге 鱼 yú?","options":["ü","u","i"],"correct":0}]}'),
  ('hsk0-07-diphthongs', 1, 'fact', '{"emoji":"🎢","title":"Скольжение от сильного звука к слабому","text":"Когда две гласные стоят рядом, они сливаются в один плавный звук (дифтонг). Первая буква звучит долго и чётко, вторая — коротко и мягко."}'),
  ('hsk0-07-diphthongs', 2, 'theory', '{"title":"Четыре основных дифтонга","blocks":[{"t":"chart","cols":4,"cells":[["ai (爱 ài)","爱"],["ei (北 běi)","北"],["ao (好 hǎo)","好"],["ou (头 tóu)","头"]]},{"t":"table","head":["Финаль","Как читается","Пример"],"rows":[["ai","Долгое «а» + короткое «и» (как «ай»)","爱 ài"],["ei","Долгое «э» + короткое «и» (как «эй»)","北 běi"],["ao","Широкое «а» + короткое «о/у» (не «ау»!)","好 hǎo"],["ou","Округлённое «о» + короткое «у» («оу»)","头 tóu"]]},{"t":"tip","text":"В ao вторая буква — именно «о», а не «у»: не вытягивайте губы в конце слога 好 hǎo."}]}'),
  ('hsk0-07-diphthongs', 3, 'game', '{"type":"listen","title":"Определите финаль на слух","items":[{"say":"爱","options":["ai","ei","ao","ou"],"correct":0},{"say":"北","options":["ai","ei","ao","ou"],"correct":1},{"say":"好","options":["ai","ei","ao","ou"],"correct":2},{"say":"头","options":["ai","ei","ao","ou"],"correct":3},{"say":"好","options":["ao","ou"],"correct":0},{"say":"头","options":["ao","ou"],"correct":1},{"say":"爱","options":["ai","ei"],"correct":0},{"say":"北","options":["ai","ei"],"correct":1}]}'),
  ('hsk0-07-diphthongs', 4, 'game', '{"type":"match","title":"Найдите пару","pairs":[["ai","爱 ài"],["ei","北 běi"],["ao","好 hǎo"],["ou","头 tóu"]]}'),
  ('hsk0-07-diphthongs', 5, 'quiz', '{"title":"Проверим","qs":[{"q":"Какая финаль в слове 好 hǎo?","options":["ao","ou","ai"],"correct":0},{"q":"Какая финаль в слове 头 tóu?","options":["ou","ao","ei"],"correct":0},{"q":"Какая гласная в дифтонге звучит длиннее и ярче?","options":["Первая","Вторая","Обе одинаково"],"correct":0},{"q":"В финали ao в конце произносится мягкое «о», а не твёрдое «у».","tf":true},{"q":"Какая финаль в слове 爱 ài?","options":["ai","ei","ao"],"correct":0},{"q":"Какая финаль в слове 北 běi?","options":["ei","ai","ou"],"correct":0}]}'),
  ('hsk0-08-i-u-v-finals', 1, 'fact', '{"emoji":"✂️","title":"Скрытые буквы в iu и ui","text":"В пиньине есть два сокращения для экономии места: iou пишется как iu (六 liù), а uei — как ui (水 shuǐ). Но при чтении средний звук слегка слышен!"}'),
  ('hsk0-08-i-u-v-finals', 2, 'theory', '{"title":"Девять составных финалей","blocks":[{"t":"chart","cols":3,"cells":[["ia (家 jiā)","家"],["ie (写 xiě)","写"],["iao (小 xiǎo)","小"],["iu (六 liù)","六"],["ua (花 huā)","花"],["uo (我 wǒ)","我"],["uai (快 kuài)","快"],["ui (水 shuǐ)","水"],["üe (月 yuè)","月"]]},{"t":"table","head":["Группа","Финали","На что обратить внимание"],"rows":[["На i-","ia, ie, iao, iu","iu = iou (между i и u слышен призвук «о»)"],["На u-","ua, uo, uai, ui","ui = uei (между u и i слышен призвук «э»)"],["На ü-","üe","Губы трубочкой переходят в растянутое «э»"]]},{"t":"tip","text":"Обратите внимание: ie (写 xiě) и üe (月 yuè) отличаются только положением губ в начале!"}]}'),
  ('hsk0-08-i-u-v-finals', 3, 'game', '{"type":"listen","title":"Послушайте и выберите финаль","items":[{"say":"家","options":["ia","ie","iao","iu"],"correct":0},{"say":"写","options":["ia","ie","iao","iu"],"correct":1},{"say":"小","options":["ia","ie","iao","iu"],"correct":2},{"say":"六","options":["ia","ie","iao","iu"],"correct":3},{"say":"花","options":["ua","uo","uai","ui"],"correct":0},{"say":"我","options":["ua","uo","uai","ui"],"correct":1},{"say":"快","options":["ua","uo","uai","ui"],"correct":2},{"say":"水","options":["ua","uo","uai","ui"],"correct":3},{"say":"月","options":["ie","üe","uo"],"correct":1}]}'),
  ('hsk0-08-i-u-v-finals', 4, 'game', '{"type":"match","title":"Соедините финаль и пример","pairs":[["ia","家 jiā"],["iao","小 xiǎo"],["iu","六 liù"],["uo","我 wǒ"],["ui","水 shuǐ"],["üe","月 yuè"]]}'),
  ('hsk0-08-i-u-v-finals', 5, 'quiz', '{"title":"Проверим","qs":[{"q":"Какой полный вид скрывается за записью iu (六 liù)?","options":["iou","iau","ieu"],"correct":0},{"q":"Какой полный вид скрывается за записью ui (水 shuǐ)?","options":["uei","uai","uoi"],"correct":0},{"q":"Какая финаль в слове 月 yuè?","options":["üe","ie","uo"],"correct":0},{"q":"Какая финаль в слове 小 xiǎo?","options":["iao","ia","iu"],"correct":0},{"q":"В слоге 水 shuǐ между u и i слышен лёгкий призвук «э».","tf":true},{"q":"Какая финаль в слове 我 wǒ?","options":["uo","ua","ou"],"correct":0}]}'),
  ('hsk0-09-nasal-finals', 1, 'fact', '{"emoji":"👃","title":"Передний -n и задний -ng","text":"В русском языке нет разницы между «н» и «нг», а в китайском она меняет смысл слова: 山 shān («гора») и 上 shàng («верх») различаются только положением языка в конце!"}'),
  ('hsk0-09-nasal-finals', 2, 'theory', '{"title":"Два типа носовых финалей","blocks":[{"t":"table","head":["Окончание","Где язык","Финали","Примеры"],"rows":[["-n (передний)","Кончик языка упирается в верхние зубы","an, en, in, un, ün, ian, uan, üan","山 shān, 门 mén, 您 nín"],["-ng (задний)","Корень языка поднимается к мягкому нёбу, звук в нос","ang, eng, ing, ong, iang, uang, iong","上 shàng, 灯 dēng, 星 xīng, 中 zhōng"],["er (особый)","Кончик языка загибается вверх к нёбу","er","二 èr (два)"]]},{"t":"chart","cols":4,"cells":[["an (山 shān)","山"],["ang (上 shàng)","上"],["en (门 mén)","门"],["eng (灯 dēng)","灯"],["in (您 nín)","您"],["ing (星 xīng)","星"],["ong (中 zhōng)","中"],["er (二 èr)","二"]]},{"t":"tip","text":"Чтобы сказать -ng правильно, начните говорить слово «банк», но остановитесь перед «к» — язык сам встанет в нужное место!"}]}'),
  ('hsk0-09-nasal-finals', 3, 'game', '{"type":"listen","title":"Передний -n или задний -ng?","items":[{"say":"山","options":["an","ang"],"correct":0},{"say":"上","options":["an","ang"],"correct":1},{"say":"门","options":["en","eng"],"correct":0},{"say":"灯","options":["en","eng"],"correct":1},{"say":"您","options":["in","ing"],"correct":0},{"say":"星","options":["in","ing"],"correct":1},{"say":"中","options":["on","ong"],"correct":1},{"say":"二","options":["en","er"],"correct":1}]}'),
  ('hsk0-09-nasal-finals', 4, 'game', '{"type":"match","title":"Найдите пару","pairs":[["an","山 shān"],["ang","上 shàng"],["en","门 mén"],["eng","灯 dēng"],["ing","星 xīng"],["ong","中 zhōng"]]}'),
  ('hsk0-09-nasal-finals', 5, 'quiz', '{"title":"Итог по гласным","qs":[{"q":"Где находится язык при произнесении -n (山 shān)?","options":["Кончик языка у верхних зубов","Загнут назад","Губы сомкнуты"],"correct":0},{"q":"Куда идёт звук при произнесении -ng (上 shàng)?","options":["В нос (корень языка поднят к нёбу)","Между зубов","Как русское «г» в конце"],"correct":0},{"q":"Как произносится финаль er (二 èr)?","options":["Кончик языка загибается вверх","Как обычное «эр» с вибрацией","В нос"],"correct":0},{"q":"Слова 山 shān и 上 shàng отличаются тоном и носовой финалью.","tf":true},{"q":"Какая финаль в слоге 中 zhōng?","options":["ong","on","eng"],"correct":0},{"q":"Какая финаль в слоге 星 xīng?","options":["ing","in","eng"],"correct":0}]}'),
  ('hsk0-10-bpmf', 1, 'fact', '{"emoji":"📄","title":"Главный секрет: не звонкость, а выдох","text":"В русском языке «б» и «п» различаются голосом. В китайском обе буквы глухие, но b произносится без выдоха, а p — с мощным толчком воздуха (листок бумаги перед губами должен отклониться!)."}'),
  ('hsk0-10-bpmf', 2, 'theory', '{"title":"Группа 1: губные (b, p, m, f)","blocks":[{"t":"chart","cols":4,"cells":[["b (爸 bà)","爸"],["p (怕 pà)","怕"],["m (妈 mā)","妈"],["f (发 fā)","发"]]},{"t":"table","head":["Инициаль","Как произносить","Пример"],"rows":[["b","Полузвонкое/глухое «п» без выдоха","爸 bà"],["p","«П» с сильным выдохом","怕 pà"],["m","Как русское «м»","妈 mā"],["f","Как русское «ф»","发 fā"]]},{"t":"tip","text":"Проверьте себя: скажите 爸 bà — лист бумаги перед ртом не двигается. Скажите 怕 pà — лист отлетает."}]}'),
  ('hsk0-10-bpmf', 3, 'game', '{"type":"listen","title":"Послушайте и выберите согласный","items":[{"say":"爸","options":["b","p"],"correct":0},{"say":"怕","options":["b","p"],"correct":1},{"say":"妈","options":["m","f"],"correct":0},{"say":"发","options":["m","f"],"correct":1},{"say":"爸","options":["b","p","m","f"],"correct":0},{"say":"怕","options":["b","p","m","f"],"correct":1},{"say":"妈","options":["b","p","m","f"],"correct":2},{"say":"发","options":["b","p","m","f"],"correct":3}]}'),
  ('hsk0-10-bpmf', 4, 'game', '{"type":"match","title":"Найдите пару","pairs":[["b","爸 bà"],["p","怕 pà"],["m","妈 mā"],["f","发 fā"]]}'),
  ('hsk0-10-bpmf', 5, 'quiz', '{"title":"Проверим","qs":[{"q":"Чем китайское b отличается от p?","options":["p произносится с сильным выдохом, b — без выдоха","b звонкое как русское «б», p глухое","Ничем"],"correct":0},{"q":"Если поднести лист бумаги ко рту, при слоге 怕 pà он заметно отклонится.","tf":true},{"q":"Какой согласный звучит в слоге 妈 mā?","options":["m","b","f"],"correct":0},{"q":"Какой согласный звучит в слоге 发 fā?","options":["f","p","m"],"correct":0},{"q":"Китайское b нельзя озвончать как русское «б».","tf":true},{"q":"Какой согласный в слоге 爸 bà?","options":["b","p","m"],"correct":0}]}'),
  ('hsk0-11-dtnl', 1, 'fact', '{"emoji":"👅","title":"Язык у верхних зубов","text":"Все четыре звука этой группы образуются кончиком языка у бугорков за верхними зубами. Пара d / t работает по тому же правилу выдоха, что и b / p."}'),
  ('hsk0-11-dtnl', 2, 'theory', '{"title":"Группа 2: переднеязычные (d, t, n, l)","blocks":[{"t":"chart","cols":4,"cells":[["d (大 dà)","大"],["t (他 tā)","他"],["n (你 nǐ)","你"],["l (来 lái)","来"]]},{"t":"table","head":["Инициаль","Как произносить","Пример"],"rows":[["d","Глухое «т» без выдоха (не звонкое «д»!)","大 dà"],["t","«Т» с сильным выдохом","他 tā"],["n","Как русское «н»","你 nǐ"],["l","Мягкое «л» (кончик языка у верхних альвеол)","来 lái"]]},{"t":"tip","text":"Сравните на слух: 大 dà (без воздуха) и 他 tā (с сильным выдохом)."}]}'),
  ('hsk0-11-dtnl', 3, 'game', '{"type":"listen","title":"Какой согласный вы слышите?","items":[{"say":"大","options":["d","t"],"correct":0},{"say":"他","options":["d","t"],"correct":1},{"say":"你","options":["n","l"],"correct":0},{"say":"来","options":["n","l"],"correct":1},{"say":"大","options":["d","t","n","l"],"correct":0},{"say":"他","options":["d","t","n","l"],"correct":1},{"say":"你","options":["d","t","n","l"],"correct":2},{"say":"来","options":["d","t","n","l"],"correct":3}]}'),
  ('hsk0-11-dtnl', 4, 'game', '{"type":"match","title":"Найдите пару","pairs":[["d","大 dà"],["t","他 tā"],["n","你 nǐ"],["l","来 lái"]]}'),
  ('hsk0-11-dtnl', 5, 'quiz', '{"title":"Проверим","qs":[{"q":"Какой согласный произносится с сильным выдохом?","options":["t","d","n"],"correct":0},{"q":"Пара d / t различается наличием выдоха, а не звонкостью.","tf":true},{"q":"Какой согласный в слоге 你 nǐ?","options":["n","l","d"],"correct":0},{"q":"Какой согласный в слоге 来 lái?","options":["l","n","t"],"correct":0},{"q":"Какой согласный в слоге 大 dà?","options":["d","t","l"],"correct":0},{"q":"Какой согласный в слоге 他 tā?","options":["t","d","n"],"correct":0}]}'),
  ('hsk0-12-gkh', 1, 'fact', '{"emoji":"🌬️","title":"Гортанное «х»","text":"Китайское h не похоже на мягкое русское «х» в слове «хитрый». Оно произносится глубоко в горле — так, будто вы дышите на замёрзшие ладони."}'),
  ('hsk0-12-gkh', 2, 'theory', '{"title":"Группа 3: заднеязычные (g, k, h)","blocks":[{"t":"chart","cols":3,"cells":[["g (哥 gē)","哥"],["k (看 kàn)","看"],["h (喝 hē)","喝"]]},{"t":"table","head":["Инициаль","Как произносить","Пример"],"rows":[["g","Глухое «к» без выдоха (не звонкое «г»)","哥 gē"],["k","«К» с сильным выдохом","看 kàn"],["h","Глубокое гортанное «х» с лёгким трением","喝 hē"]]},{"t":"tip","text":"Снова работает правило пары: g — без выдоха, k — с выдохом."}]}'),
  ('hsk0-12-gkh', 3, 'game', '{"type":"listen","title":"Послушайте и выберите согласный","items":[{"say":"哥","options":["g","k"],"correct":0},{"say":"看","options":["g","k"],"correct":1},{"say":"哥","options":["g","k","h"],"correct":0},{"say":"看","options":["g","k","h"],"correct":1},{"say":"喝","options":["g","k","h"],"correct":2},{"say":"好","options":["g","k","h"],"correct":2},{"say":"高","options":["g","k","h"],"correct":0}]}'),
  ('hsk0-12-gkh', 4, 'game', '{"type":"match","title":"Найдите пару","pairs":[["g","哥 gē"],["k","看 kàn"],["h","喝 hē"]]}'),
  ('hsk0-12-gkh', 5, 'quiz', '{"title":"Проверим","qs":[{"q":"Как произносится китайское h (喝 hē)?","options":["Глубоко в горле, как будто греете руки дыханием","Как звонкое «г»","Как «к»"],"correct":0},{"q":"Чем g отличается от k?","options":["k произносится с сильным выдохом, g — без выдоха","g звонкое, k глухое","Ничем"],"correct":0},{"q":"Какой согласный в слоге 好 hǎo?","options":["h","g","k"],"correct":0},{"q":"В слоге 哥 gē согласный g читается без выдоха.","tf":true},{"q":"Какой согласный в слоге 看 kàn?","options":["k","g","h"],"correct":0}]}'),
  ('hsk0-13-jqx', 1, 'fact', '{"emoji":"🧲","title":"Дружат только с i и ü","text":"Согласные j, q, x — «привередливые»: они никогда не стоят перед a, o, e, u. После них всегда идёт только i или ü (или финали, начинающиеся с них)."}'),
  ('hsk0-13-jqx', 2, 'theory', '{"title":"Группа 4: среднеязычные мягкие (j, q, x)","blocks":[{"t":"chart","cols":3,"cells":[["j (家 jiā)","家"],["q (去 qù)","去"],["x (西 xī)","西"]]},{"t":"table","head":["Инициаль","Как произносить","Пример"],"rows":[["j","Мягкое «дзь / чь» без выдоха","家 jiā"],["q","Мягкое «чь» с сильным выдохом","去 qù"],["x","Мягкое шепелявое «сь» (язык опущен вниз)","西 xī"]]},{"t":"tip","text":"Запомните: q — это не «к»! В слове 七 qī («семь») слышится мягкое «чи» с выдохом."}]}'),
  ('hsk0-13-jqx', 3, 'game', '{"type":"listen","title":"Послушайте и выберите согласный","items":[{"say":"家","options":["j","q"],"correct":0},{"say":"去","options":["j","q"],"correct":1},{"say":"家","options":["j","q","x"],"correct":0},{"say":"去","options":["j","q","x"],"correct":1},{"say":"西","options":["j","q","x"],"correct":2},{"say":"七","options":["j","q","x"],"correct":1},{"say":"小","options":["j","q","x"],"correct":2}]}'),
  ('hsk0-13-jqx', 4, 'game', '{"type":"match","title":"Найдите пару","pairs":[["j","家 jiā"],["q","去 qù"],["x","西 xī"]]}'),
  ('hsk0-13-jqx', 5, 'quiz', '{"title":"Проверим","qs":[{"q":"С какими гласными сочетаются j, q, x?","options":["Только с i и ü","С любыми гласными","Только с a и o"],"correct":0},{"q":"Как читается согласный q (七 qī)?","options":["Мягкое «чь» с сильным выдохом","Как «к»","Как «ц»"],"correct":0},{"q":"Как читается согласный x (西 xī)?","options":["Мягкое «сь»","Как «кс»","Как «х»"],"correct":0},{"q":"Согласный j читается без выдоха, а q — с выдохом.","tf":true},{"q":"Какой согласный в слоге 小 xiǎo?","options":["x","j","q"],"correct":0}]}'),
  ('hsk0-14-zhchshr', 1, 'fact', '{"emoji":"🥄","title":"Позиция ложки","text":"Чтобы произнести zh, ch, sh, r, кончик языка нужно загнуть вверх к твёрдому нёбу (как будто держите во рту перевёрнутую ложку). Поэтому их называют ретрофлексными («загнутыми»)."}'),
  ('hsk0-14-zhchshr', 2, 'theory', '{"title":"Группа 5: загнутые (zh, ch, sh, r)","blocks":[{"t":"chart","cols":4,"cells":[["zh (这 zhè)","这"],["ch (吃 chī)","吃"],["sh (是 shì)","是"],["r (日 rì)","日"]]},{"t":"table","head":["Инициаль","Как произносить","Пример"],"rows":[["zh","Твёрдое «чж» без выдоха (язык загнут)","这 zhè"],["ch","Твёрдое «ч» с сильным выдохом (язык загнут)","吃 chī"],["sh","Твёрдое «ш» (язык загнут)","是 shì"],["r","Среднее между «ж» и английским «r» (без вибрации!)","日 rì"]]},{"t":"tip","text":"Важное правило чтения: после zh, ch, sh, r буква i читается как глухое «ы» (吃 chī, 是 shì, 日 rì)."}]}'),
  ('hsk0-14-zhchshr', 3, 'game', '{"type":"listen","title":"Какой загнутый согласный звучит?","items":[{"say":"这","options":["zh","ch"],"correct":0},{"say":"吃","options":["zh","ch"],"correct":1},{"say":"这","options":["zh","ch","sh","r"],"correct":0},{"say":"吃","options":["zh","ch","sh","r"],"correct":1},{"say":"是","options":["zh","ch","sh","r"],"correct":2},{"say":"日","options":["zh","ch","sh","r"],"correct":3},{"say":"中","options":["zh","ch","sh","r"],"correct":0},{"say":"十","options":["zh","ch","sh","r"],"correct":2}]}'),
  ('hsk0-14-zhchshr', 4, 'game', '{"type":"match","title":"Найдите пару","pairs":[["zh","这 zhè"],["ch","吃 chī"],["sh","是 shì"],["r","日 rì"]]}'),
  ('hsk0-14-zhchshr', 5, 'quiz', '{"title":"Проверим","qs":[{"q":"Как читается буква i в слогах zhi, chi, shi, ri?","options":["Как твёрдое протяжное «ы»","Как мягкое «и»","Не читается"],"correct":0},{"q":"Где находится кончик языка при zh, ch, sh, r?","options":["Загнут вверх к нёбу","У нижних зубов","Между зубами"],"correct":0},{"q":"Чем zh отличается от ch?","options":["ch произносится с сильным выдохом, zh — без выдоха","Ничем","zh мягкое, ch твёрдое"],"correct":0},{"q":"При произнесении китайского r кончик языка не вибрирует, как в русском «р».","tf":true},{"q":"Какой согласный в слоге 十 shí?","options":["sh","zh","ch"],"correct":0}]}'),
  ('hsk0-15-zcs', 1, 'fact', '{"emoji":"⚖️","title":"Плоский язык против загнутого","text":"Звуки z, c, s — прямые родственники zh, ch, sh, но язык при них лежит плоско, упираясь кончиком в нижние зубы. Сравните: 是 shì («быть») и 四 sì («четыре»)."}'),
  ('hsk0-15-zcs', 2, 'theory', '{"title":"Группа 6: свистящие (z, c, s)","blocks":[{"t":"chart","cols":3,"cells":[["z (字 zì)","字"],["c (次 cì)","次"],["s (四 sì)","四"]]},{"t":"table","head":["Инициаль","Как произносить","Пример","Пара для сравнения"],"rows":[["z","«Дз / ц» без выдоха (язык у зубов)","字 zì","zh (这 zhè)"],["c","«Ц» с сильным выдохом (язык у зубов)","次 cì","ch (吃 chī)"],["s","Обычное «с» (язык у зубов)","四 sì","sh (是 shì)"]]},{"t":"tip","text":"Как и после zh/ch/sh, после z, c, s буква i читается как «ы»: 字 zì, 次 cì, 四 sì."}]}'),
  ('hsk0-15-zcs', 3, 'game', '{"type":"listen","title":"Различаем свистящие и загнутые","items":[{"say":"字","options":["z","c","s"],"correct":0},{"say":"次","options":["z","c","s"],"correct":1},{"say":"四","options":["z","c","s"],"correct":2},{"say":"这","options":["zh","z"],"correct":0},{"say":"字","options":["zh","z"],"correct":1},{"say":"吃","options":["ch","c"],"correct":0},{"say":"次","options":["ch","c"],"correct":1},{"say":"是","options":["sh","s"],"correct":0},{"say":"四","options":["sh","s"],"correct":1}]}'),
  ('hsk0-15-zcs', 4, 'game', '{"type":"match","title":"Найдите пару","pairs":[["z","字 zì"],["c","次 cì"],["s","四 sì"],["zh","这 zhè"],["ch","吃 chī"],["sh","是 shì"]]}'),
  ('hsk0-15-zcs', 5, 'quiz', '{"title":"Итог по согласным","qs":[{"q":"Чем слоги 字 zì и 四 sì похожи по чтению гласной?","options":["В обоих случаях i читается как «ы»","В обоих случаях i читается как «и»","Они читаются одинаково"],"correct":0},{"q":"Чем s (四 sì) отличается от sh (是 shì)?","options":["При s язык лежит плоско у зубов, при sh загнут вверх","При s есть выдох","Ничем"],"correct":0},{"q":"Как произносится c (次 cì)?","options":["Как «ц» с сильным выдохом","Как «к»","Как «с»"],"correct":0},{"q":"Согласный z произносится без выдоха, а c — с сильным выдохом.","tf":true},{"q":"Какой согласный в слоге 三 sān?","options":["s","sh","c"],"correct":0}]}'),
  ('hsk0-16-four-tones', 1, 'fact', '{"emoji":"🎵","title":"Тон меняет смысл слова","text":"В китайском мелодия голоса так же важна, как и сами буквы. Один и тот же слог ma с разными тонами означает совершенно разные вещи: 妈 mā («мама») и 马 mǎ («лошадь»)."}'),
  ('hsk0-16-four-tones', 2, 'theory', '{"title":"Ассоциации для запоминания четырёх тонов","blocks":[{"t":"table","head":["Тон","Знак","Высота","Ассоциация-подсказка","Пример"],"rows":[["1-й","ˉ","5 → 5","Ровная высокая нота у врача: «а-а-а»","妈 mā (мама)"],["2-й","ˊ","3 → 5","Удивлённый вопрос: «а?!» или «да ладно?!»","来 lái (приходить)"],["3-й","ˇ","2 → 1 → 4","Задумчивое «ну-у-у…» (нырок вниз и подъём)","马 mǎ (лошадь)"],["4-й","ˋ","5 → 1","Резкий приказ или согласие: «да!»","大 dà (большой)"]]},{"t":"chart","cols":4,"cells":[["妈 mā (1-й)","妈"],["来 lái (2-й)","来"],["马 mǎ (3-й)","马"],["大 dà (4-й)","大"]]},{"t":"tip","text":"В быстрой речи 3-й тон часто произносится только как низкий нырок вниз (2 → 1), без высокого хвостика в конце."}]}'),
  ('hsk0-16-four-tones', 3, 'game', '{"type":"listen","title":"Послушайте и определите тон","items":[{"say":"妈","options":["1-й тон: ровный (ˉ)","2-й тон: вверх (ˊ)","3-й тон: вниз-вверх (ˇ)","4-й тон: резко вниз (ˋ)"],"correct":0},{"say":"来","options":["1-й тон: ровный (ˉ)","2-й тон: вверх (ˊ)","3-й тон: вниз-вверх (ˇ)","4-й тон: резко вниз (ˋ)"],"correct":1},{"say":"马","options":["1-й тон: ровный (ˉ)","2-й тон: вверх (ˊ)","3-й тон: вниз-вверх (ˇ)","4-й тон: резко вниз (ˋ)"],"correct":2},{"say":"大","options":["1-й тон: ровный (ˉ)","2-й тон: вверх (ˊ)","3-й тон: вниз-вверх (ˇ)","4-й тон: резко вниз (ˋ)"],"correct":3},{"say":"一","options":["1-й тон: ровный (ˉ)","2-й тон: вверх (ˊ)","3-й тон: вниз-вверх (ˇ)","4-й тон: резко вниз (ˋ)"],"correct":0},{"say":"人","options":["1-й тон: ровный (ˉ)","2-й тон: вверх (ˊ)","3-й тон: вниз-вверх (ˇ)","4-й тон: резко вниз (ˋ)"],"correct":1},{"say":"好","options":["1-й тон: ровный (ˉ)","2-й тон: вверх (ˊ)","3-й тон: вниз-вверх (ˇ)","4-й тон: резко вниз (ˋ)"],"correct":2},{"say":"去","options":["1-й тон: ровный (ˉ)","2-й тон: вверх (ˊ)","3-й тон: вниз-вверх (ˇ)","4-й тон: резко вниз (ˋ)"],"correct":3}]}'),
  ('hsk0-16-four-tones', 4, 'game', '{"type":"match","title":"Соедините тон и описание","pairs":[["1-й тон (ˉ)","ровный высокий голос (妈 mā)"],["2-й тон (ˊ)","резкий подъём вверх, как вопрос (来 lái)"],["3-й тон (ˇ)","низкий нырок вниз-вверх (马 mǎ)"],["4-й тон (ˋ)","резкое падение вниз, как приказ (大 dà)"]]}'),
  ('hsk0-16-four-tones', 5, 'quiz', '{"title":"Проверим","qs":[{"q":"Какой тон звучит как удивлённый вопрос «а?!» (3 → 5)?","options":["2-й тон (ˊ)","1-й тон (ˉ)","4-й тон (ˋ)"],"correct":0},{"q":"Какой тон звучит как резкий приказ «да!» (5 → 1)?","options":["4-й тон (ˋ)","3-й тон (ˇ)","2-й тон (ˊ)"],"correct":0},{"q":"Какой тон у слова 好 hǎo?","options":["3-й тон (ˇ)","1-й тон (ˉ)","4-й тон (ˋ)"],"correct":0},{"q":"Какой тон у слова 妈 mā?","options":["1-й тон (ˉ)","2-й тон (ˊ)","3-й тон (ˇ)"],"correct":0},{"q":"От тона зависит лексическое значение китайского слова.","tf":true}]}'),
  ('hsk0-17-neutral-tone', 1, 'fact', '{"emoji":"🪶","title":"Лёгкий и безударный","text":"Кроме четырёх основных тонов в китайском есть пятый — нейтральный (轻声 qīngshēng). Над ним не ставят никакого значка, а произносят его очень коротко и легко."}'),
  ('hsk0-17-neutral-tone', 2, 'theory', '{"title":"Где встречается нейтральный тон","blocks":[{"t":"table","head":["Где бывает","Пример","Как читать"],"rows":[["Второй слог в семейных словах","妈妈 māma, 爸爸 bàba","Первый слог чётко, второй — коротко и тихо"],["Вопросительная частица","吗 ma (你好吗 nǐ hǎo ma?)","Короткое «ма» без нажима"],["Частые слова вежливости","谢谢 xièxie, 朋友 péngyou","Второй слог безударный"]]},{"t":"ex","zh":"妈妈","py":"māma","m":"мама"},{"t":"ex","zh":"爸爸","py":"bàba","m":"папа"},{"t":"ex","zh":"谢谢","py":"xièxie","m":"спасибо"},{"t":"tip","text":"Не тяните нейтральный слог: он в два раза короче обычного."}]}'),
  ('hsk0-17-neutral-tone', 3, 'game', '{"type":"match","title":"Определите рисунок тонов","pairs":[["妈妈 māma","1-й + нейтральный (мама)"],["爸爸 bàba","4-й + нейтральный (папа)"],["好吗 hǎo ma","3-й + вопросительная частица"],["朋友 péngyou","2-й + нейтральный (друг)"],["我们 wǒmen","3-й + показатель множественного числа"]]}'),
  ('hsk0-17-neutral-tone', 4, 'quiz', '{"title":"Проверим","qs":[{"q":"Как обозначается нейтральный тон на письме?","options":["Никак — над гласной нет знака тона","Точкой сверху","Волнистой линией"],"correct":0},{"q":"Как произносится слог с нейтральным тоном?","options":["Коротко, легко и безударно","Очень высоко и долго","Резко вниз"],"correct":0},{"q":"В каком слове второй слог нейтральный?","options":["爸爸 bàba","中国 Zhōngguó","再见 zàijiàn"],"correct":0},{"q":"В слове 谢谢 xièxie оба слога читаются 4-м тоном.","tf":false,"explain":"Второй слог в 谢谢 xièxie — нейтральный."},{"q":"Как по-китайски называется нейтральный тон?","options":["轻声 qīngshēng («лёгкий звук»)","普通话 pǔtōnghuà","汉字 hànzì"],"correct":0}]}'),
  ('hsk0-18-tone-pairs-ear', 1, 'fact', '{"emoji":"🎧","title":"Главные ловушки для уха","text":"Новички чаще всего путают две пары: 1-й и 2-й тон (оба заканчиваются наверху) и 3-й и 4-й тон (оба идут вниз). Потренируем их отдельно!"}'),
  ('hsk0-18-tone-pairs-ear', 2, 'theory', '{"title":"Как не путать похожие тоны","blocks":[{"t":"table","head":["Пара","В чём разница","Сравните"],"rows":[["1-й (ˉ) vs 2-й (ˊ)","1-й сразу высокий и ровный; 2-й стартует из середины и летит вверх","妈 mā vs 麻 má"],["3-й (ˇ) vs 4-й (ˋ)","3-й низкий и мягкий (хриплый внизу); 4-й резкий и короткий удар сверху вниз","马 mǎ vs 骂 mà"]]},{"t":"chart","cols":4,"cells":[["1-й: 妈 mā","妈"],["2-й: 麻 má","麻"],["3-й: 马 mǎ","马"],["4-й: 骂 mà","骂"]]},{"t":"tip","text":"Секрет: 3-й тон звучит глубоко внизу (иногда с лёгким «скрипом» голоса), а 4-й падает с самого верха."}]}'),
  ('hsk0-18-tone-pairs-ear', 3, 'game', '{"type":"listen","title":"Тренажёр слуха: выберите тон","items":[{"say":"妈","options":["1-й тон (ˉ)","2-й тон (ˊ)"],"correct":0},{"say":"麻","options":["1-й тон (ˉ)","2-й тон (ˊ)"],"correct":1},{"say":"一","options":["1-й тон (ˉ)","2-й тон (ˊ)"],"correct":0},{"say":"人","options":["1-й тон (ˉ)","2-й тон (ˊ)"],"correct":1},{"say":"马","options":["3-й тон (ˇ)","4-й тон (ˋ)"],"correct":0},{"say":"骂","options":["3-й тон (ˇ)","4-й тон (ˋ)"],"correct":1},{"say":"好","options":["3-й тон (ˇ)","4-й тон (ˋ)"],"correct":0},{"say":"大","options":["3-й тон (ˇ)","4-й тон (ˋ)"],"correct":1},{"say":"水","options":["3-й тон (ˇ)","4-й тон (ˋ)"],"correct":0},{"say":"去","options":["3-й тон (ˇ)","4-й тон (ˋ)"],"correct":1}]}'),
  ('hsk0-18-tone-pairs-ear', 4, 'quiz', '{"title":"Проверим","qs":[{"q":"Почему 1-й и 2-й тоны часто путают?","options":["Оба заканчиваются на высокой ноте, но 2-й идёт снизу вверх","Оба идут вниз","Оба нейтральные"],"correct":0},{"q":"Чем 3-й тон (马 mǎ) отличается от 4-го (骂 mà)?","options":["3-й низкий и плавный, 4-й резкий сверху вниз","3-й выше 4-го","Ничем"],"correct":0},{"q":"Какой тон у слова 去 qù?","options":["4-й тон (ˋ)","3-й тон (ˇ)","1-й тон (ˉ)"],"correct":0},{"q":"Какой тон у слова 人 rén?","options":["2-й тон (ˊ)","1-й тон (ˉ)","4-й тон (ˋ)"],"correct":0}]}'),
  ('hsk0-19-sandhi-third-tone', 1, 'fact', '{"emoji":"🗣️","title":"Язык экономит силы","text":"Произнести два низких 3-х тона подряд физически тяжело. Поэтому китайцы автоматически меняют первый 3-й тон на 2-й! Именно так звучит самое известное слово 你好."}'),
  ('hsk0-19-sandhi-third-tone', 2, 'theory', '{"title":"Правило двух третьих тонов","blocks":[{"t":"table","head":["Как пишется","Как произносится","Значение"],"rows":[["nǐ (3) + hǎo (3)","ní (2) + hǎo (3)","здравствуйте (你好)"],["hěn (3) + hǎo (3)","hén (2) + hǎo (3)","очень хорошо (很好)"],["wǒ (3) + hěn (3) + hǎo (3)","wó (2) + hén (2) + hǎo (3)","у меня всё хорошо (我很好)"]]},{"t":"ex","zh":"你好","py":"nǐ hǎo → читаем ní hǎo","m":"здравствуйте"},{"t":"ex","zh":"很好","py":"hěn hǎo → читаем hén hǎo","m":"очень хорошо"},{"t":"tip","text":"Важно: в учебниках и словарях в пиньине всегда оставляют исходный знак (nǐ hǎo), но вслух мы читаем ní hǎo!"}]}'),
  ('hsk0-19-sandhi-third-tone', 3, 'game', '{"type":"match","title":"Как это прочитать вслух?","pairs":[["你好 nǐ hǎo","читаем: ní hǎo (2 + 3)"],["很好 hěn hǎo","читаем: hén hǎo (2 + 3)"],["可以 kěyǐ","читаем: kéyǐ (2 + 3)"],["水果 shuǐguǒ","читаем: shuíguǒ (2 + 3)"],["好人 hǎo rén (3 + 2)","остаётся 3 + 2 (меняется только перед 3-м)"]]}'),
  ('hsk0-19-sandhi-third-tone', 4, 'quiz', '{"title":"Проверим правило 3 + 3","qs":[{"q":"Как на самом деле произносится 你好 nǐ hǎo?","options":["ní hǎo (2-й + 3-й)","nǐ hào (3-й + 4-й)","nì hǎo (4-й + 3-й)"],"correct":0},{"q":"Как произносится 很好 hěn hǎo?","options":["hén hǎo (2-й + 3-й)","hèn hǎo (4-й + 3-й)","hēn hǎo (1-й + 3-й)"],"correct":0},{"q":"Если за 3-м тоном идёт 1-й, 2-й или 4-й тон, он НЕ превращается во 2-й.","tf":true},{"q":"На письме в пиньине знак 3-го тона исправляют на 2-й (ní hǎo).","tf":false,"explain":"На письме всегда оставляют исходный тон: nǐ hǎo."},{"q":"Как прочитать 可以 kěyǐ?","options":["kéyǐ","kèyǐ","kēyǐ"],"correct":0},{"q":"Меняется ли 3-й тон в слове 老师 lǎoshī (3 + 1)?","options":["Нет, дальше идёт 1-й тон","Да, становится 2-м","Становится 4-м"],"correct":0}]}'),
  ('hsk0-20-sandhi-bu', 1, 'fact', '{"emoji":"🚫","title":"Хамелеон отрицания","text":"Отрицательная частица 不 («не») сама по себе читается 4-м тоном: bù. Но она не любит сталкиваться с другим 4-м тоном и перед ним меняет тон на 2-й (bú)."}'),
  ('hsk0-20-sandhi-bu', 2, 'theory', '{"title":"Правило чтения 不","blocks":[{"t":"table","head":["Что идёт после 不","Как читаем 不","Пример"],"rows":[["1-й тон","bù (4-й тон, без изменений)","不高 bù gāo (невысокий)"],["2-й тон","bù (4-й тон, без изменений)","不来 bù lái (не приходить)"],["3-й тон","bù (4-й тон, без изменений)","不好 bù hǎo (нехорошо)"],["4-й тон","bú (меняется на 2-й тон!)","不是 bú shì, 不去 bú qù, 不大 bú dà"]]},{"t":"ex","zh":"不是","py":"bú shì","m":"не является"},{"t":"ex","zh":"不好","py":"bù hǎo","m":"нехорошо"},{"t":"tip","text":"Запомните одну формулу: 4 + 4 → 2 + 4 (不是 bú shì). Во всех остальных случаях остаётся bù."}]}'),
  ('hsk0-20-sandhi-bu', 3, 'game', '{"type":"match","title":"Выберите правильное чтение","pairs":[["不是 (перед 4-м)","bú shì"],["不去 (перед 4-м)","bú qù"],["不大 (перед 4-м)","bú dà"],["不好 (перед 3-м)","bù hǎo"],["不来 (перед 2-м)","bù lái"],["不高 (перед 1-м)","bù gāo"]]}'),
  ('hsk0-20-sandhi-bu', 4, 'quiz', '{"title":"Проверим слово 不","qs":[{"q":"Как читается 不 в слове 不是 («не является»)?","options":["bú shì (2-й тон)","bù shì (4-й тон)","bǔ shì (3-й тон)"],"correct":0},{"q":"Как читается 不 в слове 不好 («нехорошо»)?","options":["bù hǎo (4-й тон)","bú hǎo (2-й тон)","bū hǎo (1-й тон)"],"correct":0},{"q":"Как читается 不 в слове 不去 («не идти»)?","options":["bú qù","bù qù","bǔ qù"],"correct":0},{"q":"Как читается 不 в слове 不来 («не приходить»)?","options":["bù lái","bú lái","bū lái"],"correct":0},{"q":"Перед 1-м, 2-м и 3-м тонами слово 不 всегда читается 4-м тоном (bù).","tf":true},{"q":"Как читается 不 в слове 不大 («небольшой»)?","options":["bú dà","bù dà","bǔ dà"],"correct":0}]}'),
  ('hsk0-21-sandhi-yi', 1, 'fact', '{"emoji":"1️⃣","title":"Самое изменчивое слово","text":"Цифра 一 yī («один») меняет свой тон чаще всех в китайском языке. В зависимости от соседа справа она может звучать 1-м, 2-м или 4-м тоном!"}'),
  ('hsk0-21-sandhi-yi', 2, 'theory', '{"title":"Три правила для 一","blocks":[{"t":"table","head":["Ситуация","Тон 一","Пример"],"rows":[["При счёте, в номерах, в конце слова","yī (1-й тон)","一, 二, 三 yī, èr, sān"],["Перед 4-м тоном","yí (2-й тон)","一个 yí gè, 一样 yí yàng"],["Перед 1-м, 2-м или 3-м тоном","yì (4-й тон)","一天 yì tiān (1), 一年 yì nián (2), 一起 yì qǐ (3)"]]},{"t":"ex","zh":"一个","py":"yí gè","m":"один (перед 4-м тоном)"},{"t":"ex","zh":"一天","py":"yì tiān","m":"один день (перед 1-м тоном)"},{"t":"tip","text":"Обратите внимание: перед 4-м тоном 一 ведёт себя точно так же, как 不 — становится 2-м тоном (yí gè, bú shì)."}]}'),
  ('hsk0-21-sandhi-yi', 3, 'game', '{"type":"match","title":"Определите тон единицы","pairs":[["一, 二, 三 (счёт)","yī (1-й тон)"],["一个 gè (4-й тон)","yí gè (2-й тон)"],["一天 tiān (1-й тон)","yì tiān (4-й тон)"],["一年 nián (2-й тон)","yì nián (4-й тон)"],["一起 qǐ (3-й тон)","yì qǐ (4-й тон)"]]}'),
  ('hsk0-21-sandhi-yi', 4, 'quiz', '{"title":"Проверим слово 一","qs":[{"q":"Как читается 一 при обычном счёте (1, 2, 3)?","options":["yī (1-й тон)","yí (2-й тон)","yì (4-й тон)"],"correct":0},{"q":"Как читается 一 перед 4-м тоном (一个 gè)?","options":["yí gè (2-й тон)","yì gè (4-й тон)","yī gè (1-й тон)"],"correct":0},{"q":"Как читается 一 перед 1-м тоном (一天 tiān)?","options":["yì tiān (4-й тон)","yí tiān (2-й тон)","yī tiān (1-й тон)"],"correct":0},{"q":"Как читается 一 перед 3-м тоном (一起 qǐ)?","options":["yì qǐ (4-й тон)","yí qǐ (2-й тон)","yī qǐ (1-й тон)"],"correct":0},{"q":"Перед 4-м тоном и 不, и 一 меняются на 2-й тон (bú, yí).","tf":true},{"q":"Как читается 一 перед 2-м тоном (一年 nián)?","options":["yì nián (4-й тон)","yí nián (2-й тон)","yī nián (1-й тон)"],"correct":0}]}'),
  ('hsk0-22-spelling-yw', 1, 'fact', '{"emoji":"🛡️","title":"Защитные буквы в начале слога","text":"В пиньине слоги на i и u не любят стоять «голыми» в начале слова, чтобы не сливаться с соседними слогами. Поэтому перед ними ставят защитные буквы y или w."}'),
  ('hsk0-22-spelling-yw', 2, 'theory', '{"title":"Как записываются слоги без инициали","blocks":[{"t":"table","head":["Если слог начинается на...","Правило","Было → Стало","Пример"],"rows":[["i (одиночное)","Добавляем y спереди","i → yi","一 yī"],["ia, ie, iao, iou, ian, iang, iong","Меняем i на y","ia → ya, uo → wo","也 yě, 有 yǒu"],["u (одиночное)","Добавляем w спереди","u → wu","五 wǔ"],["ua, uo, uai, uei, uan, uang","Меняем u на w","uo → wo, uai → wai","我 wǒ, 外 wài"]]},{"t":"tip","text":"Буквы y и w не добавляют новых звуков — это просто правило орфографии!"}]}'),
  ('hsk0-22-spelling-yw', 3, 'game', '{"type":"match","title":"Как записать слог без инициали?","pairs":[["i","yi (一 yī)"],["u","wu (五 wǔ)"],["ie","ye (也 yě)"],["uo","wo (我 wǒ)"],["iou","you (有 yǒu)"],["uei","wei (为 wèi)"]]}'),
  ('hsk0-22-spelling-yw', 4, 'quiz', '{"title":"Проверим y и w","qs":[{"q":"Как правильно записать слог uo без инициали (слово «я»)?","options":["wǒ","uǒ","yǒ"],"correct":0},{"q":"Как правильно записать одиночный звук i без инициали?","options":["yi","i","wi"],"correct":0},{"q":"Как правильно записать одиночный звук u без инициали?","options":["wu","u","yu"],"correct":0},{"q":"Как записывается слог ie без инициали?","options":["ye","ie","we"],"correct":0},{"q":"Буквы y и w в начале слога пиньиня не меняют его звучание.","tf":true},{"q":"Как записывается слог iou без инициали?","options":["you","iou","wou"],"correct":0}]}'),
  ('hsk0-23-spelling-v', 1, 'fact', '{"emoji":"👀","title":"Две точки только там, где есть выбор","text":"У буквы ü (звук «юй») есть строгая логика: две точки над u пишутся ТОЛЬКО после согласных n и l, потому что после них бывает и обычное u, и ü."}'),
  ('hsk0-23-spelling-v', 2, 'theory', '{"title":"Три правила для ü","blocks":[{"t":"table","head":["Позиция","Как пишется","Почему так","Пример"],"rows":[["После n и l","Точки ОСТАЮТСЯ (nü, lü)","Чтобы отличать 女 nǚ («женщина») от 努 nǔ","女 nǚ, 绿 lǜ"],["После j, q, x","Точки ИСЧЕЗАЮТ (ju, qu, xu)","После j, q, x обычного u не бывает, путаницы нет","去 qù, 学 xué"],["В начале слога (без инициали)","Превращается в yu (yue, yuan, yun)","Добавляется y, а точки убираются","鱼 yú, 月 yuè"]]},{"t":"tip","text":"Увидели ju, qu, xu или yu — всегда читайте там звук ü («юй»), даже если точек нет!"}]}'),
  ('hsk0-23-spelling-v', 3, 'game', '{"type":"match","title":"Выберите правильную запись","pairs":[["n + ü","nü (точки остаются: 女 nǚ)"],["l + ü","lü (точки остаются: 绿 lǜ)"],["q + ü","qu (точки исчезают: 去 qù)"],["x + üe","xue (точки исчезают: 学 xué)"],["ü без инициали","yu (鱼 yú)"],["üe без инициали","yue (月 yuè)"]]}'),
  ('hsk0-23-spelling-v', 4, 'quiz', '{"title":"Проверим правило ü","qs":[{"q":"После каких согласных две точки над ü ВСЕГДА сохраняются?","options":["После n и l (nǚ, lǜ)","После j, q, x","Никогда не сохраняются"],"correct":0},{"q":"Как правильно записать слог q + ü (слово 去 «идти»)?","options":["qù","qǜ","qyù"],"correct":0},{"q":"Как записывается ü без инициали (слово 鱼 «рыба»)?","options":["yú","ǜ","wú"],"correct":0},{"q":"Как читается буква u в слоге 学 xué?","options":["Как ü («юй»)","Как обычное «у»","Как «о»"],"correct":0},{"q":"После j, q, x никогда не стоит обычное u, поэтому точки над ü не нужны.","tf":true},{"q":"Как правильно записать слово «женщина»?","options":["nǚ","nǔ","nyǔ"],"correct":0}]}'),
  ('hsk0-24-tone-placement', 1, 'fact', '{"emoji":"👑","title":"Королева гласных — буква a","text":"Если в слоге несколько гласных (например, hǎo или jiā), над какой из них ставить значок тона? В пиньине есть чёткая иерархия гласных!"}'),
  ('hsk0-24-tone-placement', 2, 'theory', '{"title":"Порядок постановки знака тона и апостроф","blocks":[{"t":"table","head":["Правило","Пример","Пояснение"],"rows":[["1. Есть a — ставим на a","hǎo, jiā","Буква a всегда забирает знак тона себе"],["2. Нет a — ставим на o или e","dōu, xiě","Вторые по старшинству — o и e"],["3. Сочетания iu и ui — на ПОСЛЕДНЮЮ","liù, shuǐ","Исключение: знак падает на вторую букву"],["4. Точка над i пропадает","nǐ, yī, shì","Знак тона заменяет точку над i"],["5. Апостроф ('') разделяет слоги","Xī''ān (Сиань)","Без апострофа Xī''ān слилось бы в один слог xiān"]]},{"t":"tip","text":"Запомните цепочку старшинства: a → o / e → последняя в iu / ui."}]}'),
  ('hsk0-24-tone-placement', 3, 'game', '{"type":"match","title":"Найдите правильную запись","pairs":[["h + ao (3-й тон)","hǎo (знак на a)"],["x + ie (3-й тон)","xiě (знак на e)"],["l + iu (4-й тон)","liù (знак на u — последнюю)"],["sh + ui (3-й тон)","shuǐ (знак на i — последнюю)"],["Xī + ān","Xī''ān (нужен апостроф)"]]}'),
  ('hsk0-24-tone-placement', 4, 'quiz', '{"title":"Итог по правилам чтения","qs":[{"q":"На какую букву ставится знак тона в слоге hǎo?","options":["На a","На o","На h"],"correct":0},{"q":"На какую букву ставится знак тона в слоге liù?","options":["На u (последнюю в iu)","На i","На l"],"correct":0},{"q":"На какую букву ставится знак тона в слоге shuǐ?","options":["На i (последнюю в ui)","На u","На sh"],"correct":0},{"q":"Зачем в слове Xī''ān ставится апостроф?","options":["Чтобы разделить два слога и не прочитать их как xiān","Это знак 4-го тона","Для красоты"],"correct":0},{"q":"Когда над буквой i ставится знак тона, точка над ней исчезает (nǐ, yī).","tf":true},{"q":"На какую букву ставится знак тона в слоге xiě?","options":["На e","На i","На x"],"correct":0}]}'),
  ('hsk0-25-eight-strokes', 1, 'fact', '{"emoji":"✍️","title":"Весь китайский — из восьми штрихов","text":"Любой, даже самый сложный иероглиф из 20 черт, собирается всего из 8 базовых элементов. Выпишите их в тетрадь и пропишите каждый по строчке!"}'),
  ('hsk0-25-eight-strokes', 2, 'theory', '{"title":"Таблица восьми базовых черт","blocks":[{"t":"chart","cols":4,"cells":[["一 横 héng","横"],["丨 竖 shù","竖"],["丿 撇 piě","撇"],["丶 点 diǎn","点"],["㇏ 捺 nà","捺"],["㇀ 提 tí","提"],["乛 折 zhé","折"],["亅 钩 gōu","钩"]]},{"t":"table","head":["Черта","Название","Направление движения руки"],"rows":[["一","横 héng (горизонталь)","Строго слева направо"],["丨","竖 shù (вертикаль)","Строго сверху вниз"],["丿","撇 piě (откидная влево)","Сверху вниз и плавно влево"],["丶","点 diǎn (точка)","Короткий нажим вниз-вправо"],["㇏","捺 nà (откидная вправо)","Сверху вниз и плавно вправо"],["㇀","提 tí (восходящая)","Снизу вверх и вправо"],["乛","折 zhé (ломаная)","Смена направления под углом без отрыва ручки"],["亅","钩 gōu (крюк)","Короткий острый крючок на конце черты"]]},{"t":"tip","text":"Важно: горизонталь всегда пишется слева направо, а вертикаль — только сверху вниз!"}]}'),
  ('hsk0-25-eight-strokes', 3, 'game', '{"type":"match","title":"Найдите название черты","pairs":[["一","横 héng (горизонталь слева направо)"],["丨","竖 shù (вертикаль сверху вниз)"],["丿","撇 piě (откидная влево)"],["丶","点 diǎn (точка)"],["㇏","捺 nà (откидная вправо)"],["亅","钩 gōu (крюк)"]]}'),
  ('hsk0-25-eight-strokes', 4, 'quiz', '{"title":"Проверим черты","qs":[{"q":"В каком направлении всегда пишется горизонтальная черта 横 héng?","options":["Слева направо","Справа налево","Снизу вверх"],"correct":0},{"q":"Как называется черта 撇 piě (丿)?","options":["Откидная влево","Откидная вправо","Вертикаль"],"correct":0},{"q":"В каком направлении пишется вертикаль 竖 shù (丨)?","options":["Сверху вниз","Снизу вверх","Слева направо"],"correct":0},{"q":"Сколько базовых черт лежит в основе китайской письменности?","options":["Восемь","Три","Двадцать шесть"],"correct":0},{"q":"Ломаная черта 折 zhé пишется одним движением, без отрыва ручки на углу.","tf":true},{"q":"Как называется короткий крючок на конце черты (亅)?","options":["钩 gōu","点 diǎn","横 héng"],"correct":0}]}'),
  ('hsk0-26-stroke-order-rules', 1, 'fact', '{"emoji":"🧭","title":"Почему порядок черт обязателен","text":"Если писать иероглиф в случайном порядке, он получится кривым, а телефон или словарь не распознает рукописный ввод. Семь простых правил решают 99% случаев."}'),
  ('hsk0-26-stroke-order-rules', 2, 'theory', '{"title":"Таблица правил написания","blocks":[{"t":"table","head":["Правило","Пример","Как пишем"],"rows":[["1. Сверху вниз","三 sān (три)","Верхняя черта → средняя → нижняя"],["2. Слева направо","川 chuān (река)","Левая черта → средняя → правая"],["3. Горизонталь раньше вертикали","十 shí (десять)","Сначала 一 (横), затем 丨 (竖)"],["4. Сначала 撇 (влево), потом 捺 (вправо)","人 rén (человек)","Сначала левая нога 丿, затем правая ㇏"],["5. Внешнее раньше внутреннего","月 yuè (луна)","Сначала контур, затем внутренние черты"],["6. Середина раньше симметричных боков","小 xiǎo (маленький)","Сначала центр 亅, затем левая и правая точки"],["7. «Вошёл и закрыл дверь»","日 rì, 国 guó","Нижняя черта рамки пишется самой последней!"]]},{"t":"tip","text":"Правило №7 особенно важно: сначала рисуем стены рамки, заполняем её внутри и только в самом конце закрываем нижнюю черту."}]}'),
  ('hsk0-26-stroke-order-rules', 3, 'game', '{"type":"match","title":"Какое правило работает в знаке?","pairs":[["三 sān","сверху вниз"],["川 chuān","слева направо"],["十 shí","горизонталь раньше вертикали"],["人 rén","сначала 撇 (влево), потом 捺 (вправо)"],["小 xiǎo","середина раньше боков"],["日 rì","нижняя черта рамки в самом конце"]]}'),
  ('hsk0-26-stroke-order-rules', 4, 'quiz', '{"title":"Проверим правила","qs":[{"q":"Какую черту пишут первой в иероглифе 十 shí («десять»)?","options":["Горизонталь 一 (横)","Вертикаль 丨 (竖)"],"correct":0},{"q":"Какую черту пишут первой в иероглифе 人 rén («человек»)?","options":["Откидную влево 丿 (撇)","Откидную вправо ㇏ (捺)"],"correct":0},{"q":"Когда пишется нижняя закрывающая черта рамки в знаках 日 rì и 国 guó?","options":["В самом конце, после заполнения середины","Самой первой","Второй"],"correct":0},{"q":"Какую часть иероглифа 小 xiǎo («маленький») пишут первой?","options":["Центральную вертикаль с крюком","Левую точку","Правую точку"],"correct":0},{"q":"В иероглифе 三 sān черты пишутся сверху вниз.","tf":true},{"q":"Какое правило действует при написании знака 川 chuān?","options":["Слева направо","Снизу вверх","Справа налево"],"correct":0}]}'),
  ('hsk0-27-writing-practice-1', 1, 'fact', '{"emoji":"📓","title":"Берём ручку и тетрадь!","text":"Сейчас мы разберём по косточкам 6 самых базовых иероглифов. Пропишите каждый в тетради 5–10 раз, проговаривая вслух названия черт и пиньинь."}'),
  ('hsk0-27-writing-practice-1', 2, 'theory', '{"title":"Разбор базовых иероглифов","blocks":[{"t":"table","head":["Знак","Пиньинь и смысл","Количество черт","Точный порядок черт"],"rows":[["一","yī (один)","1 черта","1. 横 (горизонталь)"],["二","èr (два)","2 черты","1. 横 (короткая) → 2. 横 (длинная)"],["三","sān (три)","3 черты","1. 横 → 2. 横 → 3. 横"],["十","shí (десять)","2 черты","1. 横 → 2. 竖 (вертикаль)"],["人","rén (человек)","2 черты","1. 撇 (влево) → 2. 捺 (вправо)"],["大","dà (большой)","3 черты","1. 横 → 2. 撇 → 3. 捺"]]},{"t":"tip","text":"Посмотрите на 大 dà («большой»): это просто человек 人 rén, который раскинул руки в стороны (добавилась верхняя горизонталь 一)! Поэтому первой пишется 横, а затем 人 (撇 и 捺)."}]}'),
  ('hsk0-27-writing-practice-1', 3, 'game', '{"type":"build","title":"Соберите правильный порядок черт","items":[{"target":"十 shí (десять)","answer":["横","竖"],"hint":"Соберите порядок черт для 十 shí"},{"target":"人 rén (человек)","answer":["撇","捺"],"hint":"Соберите порядок черт для 人 rén"},{"target":"大 dà (большой)","answer":["横","撇","捺"],"hint":"Соберите порядок черт для 大 dà"},{"target":"三 sān (три)","answer":["横 (верх)","横 (середина)","横 (низ)"],"hint":"Соберите порядок черт для 三 sān"},{"target":"工 gōng (работа)","answer":["横 (верх)","竖","横 (низ)"],"hint":"Соберите порядок черт для 工 gōng"}]}'),
  ('hsk0-27-writing-practice-1', 4, 'quiz', '{"title":"Проверим прописи","qs":[{"q":"Сколько черт в иероглифе 大 dà («большой»)?","options":["3 черты (横, 撇, 捺)","2 черты","4 черты"],"correct":0},{"q":"Какая черта пишется первой в иероглифе 大 dà?","options":["Горизонталь 横 (一)","Откидная влево 撇 (丿)","Откидная вправо 捺 (㇏)"],"correct":0},{"q":"Из каких двух черт состоит иероглиф 十 shí?","options":["Горизонталь 横 + вертикаль 竖","Две горизонтали","Две точки"],"correct":0},{"q":"В иероглифе 二 èr верхняя черта короче нижней, и она пишется первой.","tf":true},{"q":"Как запомнить написание 大 dà?","options":["Это человек 人 с раскинутыми руками (горизонталь сверху)","Это три горизонтали","Это квадрат"],"correct":0}]}'),
  ('hsk0-28-writing-practice-2', 1, 'fact', '{"emoji":"🧱","title":"Пишем слева направо по блокам","text":"Сложные иероглифы состоят из простых блоков. Главное правило орфографии здесь: сначала полностью пишем левую часть сверху вниз, и только потом переходим к правой!"}'),
  ('hsk0-28-writing-practice-2', 2, 'theory', '{"title":"Орфография популярных знаков","blocks":[{"t":"table","head":["Знак","Пиньинь и смысл","Левая часть (1-я)","Правая часть (2-я)","Смысловая подсказка"],"rows":[["你","nǐ (ты)","亻 (человек)","尔","Человек напротив тебя"],["好","hǎo (хорошо)","女 (женщина)","子 (ребёнок)","Женщина с ребёнком — это хорошо"],["他","tā (он)","亻 (человек)","也","Местоимение «он» с ключом человека"],["她","tā (она)","女 (женщина)","也","Звучит так же (tā), но ключ «женщина»"],["明","míng (светлый)","日 (солнце)","月 (луна)","Солнце и луна дают яркий свет"]]},{"t":"tip","text":"Сравните 他 tā и 她 tā: они произносятся абсолютно одинаково, но на письме левый ключ сразу показывает пол!"}]}'),
  ('hsk0-28-writing-practice-2', 3, 'game', '{"type":"build","title":"Соберите знак по порядку написания","items":[{"target":"好 hǎo (хорошо)","answer":["女 (левая часть)","子 (правая часть)"],"hint":"В каком порядке пишется 好 hǎo?"},{"target":"明 míng (светлый)","answer":["日 (левая часть)","月 (правая часть)"],"hint":"В каком порядке пишется 明 míng?"},{"target":"你 nǐ (ты)","answer":["亻 (левая часть)","尔 (правая часть)"],"hint":"В каком порядке пишется 你 nǐ?"},{"target":"他 tā (он)","answer":["亻 (левая часть)","也 (правая часть)"],"hint":"В каком порядке пишется 他 tā?"},{"target":"她 tā (она)","answer":["女 (левая часть)","也 (правая часть)"],"hint":"В каком порядке пишется 她 tā?"}]}'),
  ('hsk0-28-writing-practice-2', 4, 'game', '{"type":"match","title":"Соедините иероглиф и его состав","pairs":[["你 nǐ","亻 + 尔 (ты)"],["好 hǎo","女 + 子 (хорошо)"],["他 tā","亻 + 也 (он)"],["她 tā","女 + 也 (она)"],["明 míng","日 + 月 (светлый)"]]}'),
  ('hsk0-28-writing-practice-2', 5, 'quiz', '{"title":"Итог по письму","qs":[{"q":"Какую часть иероглифа 好 hǎo пишут первой?","options":["Левую часть 女 (женщина)","Правую часть 子 (ребёнок)","Нижнюю горизонталь"],"correct":0},{"q":"Чем на письме отличаются 他 tā («он») и 她 tā («она»)?","options":["Левым ключом: 亻 (человек) у «он» и 女 (женщина) у «она»","Правой частью","Ничем, пишутся одинаково"],"correct":0},{"q":"Из каких двух частей состоит иероглиф 明 míng («светлый»)?","options":["日 (солнце) + 月 (луна)","木 + 木","人 + 大"],"correct":0},{"q":"В двусоставных знаках сначала полностью прописывается левая половина, затем правая.","tf":true},{"q":"Какой ключ стоит слева в слове 你 nǐ («ты»)?","options":["亻 (человек)","女 (женщина)","日 (солнце)"],"correct":0}]}'),
  ('hsk0-29-radicals-basic', 1, 'fact', '{"emoji":"🔑","title":"Ключ — это тема иероглифа","text":"Ключ (部首 bùshǒu) — смысловая часть иероглифа. Увидев незнакомый знак, по ключу можно сразу догадаться, к какой теме он относится: вода, еда, речь или человек."}'),
  ('hsk0-29-radicals-basic', 2, 'theory', '{"title":"Десять самых частых ключей","blocks":[{"t":"table","head":["Ключ","Значение","Примеры с пиньинем","Логика"],"rows":[["口","рот","吃 chī (есть), 喝 hē (пить)","Действия, связанные со ртом"],["木","дерево","林 lín (лес), 休 xiū (отдыхать)","Деревья и природа"],["日","солнце, время","明 míng (светлый), 时 shí (время)","Свет и время"],["女","женщина","妈 mā (мама), 她 tā (она)","Женский род и семья"],["讠","речь, слова","说 shuō (говорить), 谢 xiè (благодарить)","Общение и язык"],["饣","еда","饭 fàn (еда, рис), 饿 è (голодный)","Питание"],["艹","трава, растения","茶 chá (чай), 花 huā (цветок)","Чай растёт на кусте!"],["门","дверь, ворота","问 wèn (спрашивать), 间 jiān (комната)","Вход и помещение"],["宀","крыша","家 jiā (дом, семья), 字 zì (иероглиф)","Свинья под крышей = дом 家"],["辶","дорога, движение","这 zhè (это), 远 yuǎn (далеко)","Путь и перемещение"]]},{"t":"tip","text":"Попробуйте найти лишний знак глазами: 河 hé, 海 hǎi, 妈 mā — лишний 妈 mā, потому что у него ключ 女, а не вода!"}]}'),
  ('hsk0-29-radicals-basic', 3, 'game', '{"type":"match","title":"Соедините ключ и его смысл","pairs":[["口","рот (吃 chī, 喝 hē)"],["讠","речь (说 shuō, 谢 xiè)"],["饣","еда (饭 fàn)"],["艹","растения (茶 chá, 花 huā)"],["宀","крыша (家 jiā, 字 zì)"],["辶","дорога (远 yuǎn)"]]}'),
  ('hsk0-29-radicals-basic', 4, 'quiz', '{"title":"Проверим ключи","qs":[{"q":"Какой ключ подсказывает, что иероглиф 茶 chá («чай») связан с растениями?","options":["艹 (трава)","讠 (речь)","饣 (еда)"],"correct":0},{"q":"Какой ключ стоит в знаках 吃 chī («есть») и 喝 hē («пить»)?","options":["口 (рот)","门 (дверь)","木 (дерево)"],"correct":0},{"q":"Какой ключ стоит в слове 说 shuō («говорить»)?","options":["讠 (речь)","艹 (трава)","宀 (крыша)"],"correct":0},{"q":"Какой ключ стоит сверху в слове 家 jiā («дом»)?","options":["宀 (крыша)","口 (рот)","辶 (дорога)"],"correct":0},{"q":"Какой из этих знаков лишний по смыслу ключа?","options":["说 shuō (ключ речи 讠)","吃 chī (ключ рот 口)","喝 hē (ключ рот 口)"],"correct":0},{"q":"Ключ 饣 в слове 饭 fàn («еда, рис») связан с пищей.","tf":true}]}'),
  ('hsk0-30-radicals-chameleons', 1, 'fact', '{"emoji":"🦎","title":"Боковая форма становится узкой","text":"Когда самостоятельный иероглиф встаёт слева в качестве ключа, он «худеет» и меняет форму, чтобы уступить место правой половине знака."}'),
  ('hsk0-30-radicals-chameleons', 2, 'theory', '{"title":"Пять главных ключей-хамелеонов","blocks":[{"t":"table","head":["Полный знак","Форма слева (ключ)","Значение","Примеры"],"rows":[["人 rén","亻","человек","你 nǐ, 他 tā, 休 xiū"],["水 shuǐ","氵 («три капли воды»)","вода, жидкость","河 hé (река), 海 hǎi (море)"],["手 shǒu","扌","рука, действие рукой","打 dǎ (бить/играть)"],["心 xīn","忄","сердце, чувства","忙 máng (занятой), 快 kuài (быстрый)"],["火 huǒ","灬 («четыре точки огня» снизу)","огонь, жар","热 rè (горячий)"]]},{"t":"tip","text":"Запомните «три капли воды» 氵 — это самый частый ключ в китайском языке!"}]}'),
  ('hsk0-30-radicals-chameleons', 3, 'game', '{"type":"match","title":"Узнайте ключ-хамелеон","pairs":[["亻","человек (от 人 rén)"],["氵","вода (от 水 shuǐ)"],["扌","рука (от 手 shǒu)"],["忄","сердце (от 心 xīn)"],["灬","огонь снизу (от 火 huǒ)"]]}'),
  ('hsk0-30-radicals-chameleons', 4, 'quiz', '{"title":"Проверим хамелеонов","qs":[{"q":"От какого полного иероглифа произошёл ключ 氵 («три капли воды»)?","options":["水 shuǐ (вода)","火 huǒ (огонь)","木 mù (дерево)"],"correct":0},{"q":"Что означает боковой ключ 亻 в словах 你 nǐ и 他 tā?","options":["Человек (от 人 rén)","Рука","Сердце"],"correct":0},{"q":"Какой ключ стоит слева в глаголе 打 dǎ («бить, играть рукой»)?","options":["扌 (рука, от 手 shǒu)","氵 (вода)","忄 (сердце)"],"correct":0},{"q":"Что означают четыре точки 灬 внизу иероглифа 热 rè («горячий»)?","options":["Огонь (от 火 huǒ)","Воду","Траву"],"correct":0},{"q":"Ключ 忄 слева в слове 快 kuài произошёл от иероглифа 心 xīn («сердце»).","tf":true},{"q":"В каком из слов есть ключ воды 氵?","options":["河 hé (река)","他 tā (он)","打 dǎ (бить)"],"correct":0}]}'),
  ('hsk0-31-character-structure', 1, 'fact', '{"emoji":"🏗️","title":"Четыре архитектурные схемы","text":"Все китайские иероглифы вписываются в воображаемый квадрат по одной из четырёх схем. Понимая схему, вы сразу видите, в каком порядке писать части."}'),
  ('hsk0-31-character-structure', 2, 'theory', '{"title":"Четыре типа структуры иероглифа","blocks":[{"t":"table","head":["Тип структуры","Как устроен","Примеры"],"rows":[["1. Цельный (монолит)","Не делится на отдельные блоки","人 rén, 日 rì, 山 shān, 大 dà"],["2. Слева направо","Левый блок + правый блок","你 nǐ, 好 hǎo, 明 míng, 休 xiū"],["3. Сверху вниз","Верхний блок + нижний блок","字 zì, 家 jiā, 花 huā, 男 nán"],["4. Рамка (охватывающий)","Внешний контур + начинка внутри","国 guó, 问 wèn, 这 zhè"]]},{"t":"tip","text":"Соберите в конструкторе ниже несколько знаков из их смысловых частей!"}]}'),
  ('hsk0-31-character-structure', 3, 'game', '{"type":"build","title":"Конструктор иероглифов","items":[{"target":"好 hǎo (хорошо)","answer":["女 (женщина)","子 (ребёнок)"],"hint":"Соберите 好 hǎo"},{"target":"明 míng (светлый)","answer":["日 (солнце)","月 (луна)"],"hint":"Соберите 明 míng"},{"target":"休 xiū (отдыхать)","answer":["亻 (человек)","木 (дерево)"],"hint":"Соберите 休 xiū: человек прислонился к дереву"},{"target":"林 lín (лес)","answer":["木 (дерево)","木 (дерево)"],"hint":"Соберите 林 lín: два дерева рядом"},{"target":"男 nán (мужчина)","answer":["田 (поле)","力 (сила)"],"hint":"Соберите 男 nán: сила в поле (сверху вниз)"}]}'),
  ('hsk0-31-character-structure', 4, 'game', '{"type":"match","title":"Определите тип структуры","pairs":[["山 shān","цельный (монолит)"],["好 hǎo","слева направо"],["字 zì","сверху вниз"],["国 guó","рамка (охватывающий)"]]}'),
  ('hsk0-31-character-structure', 5, 'quiz', '{"title":"Проверим структуру","qs":[{"q":"Какой тип структуры у иероглифа 国 guó («страна»)?","options":["Рамка (охватывающий)","Слева направо","Цельный"],"correct":0},{"q":"Из каких двух ключей состоит знак 休 xiū («отдыхать»)?","options":["亻 (человек) + 木 (дерево)","日 + 月","女 + 子"],"correct":0},{"q":"Какой тип структуры у иероглифа 字 zì («иероглиф»)?","options":["Сверху вниз (крыша 宀 + ребёнок 子)","Слева направо","Цельный"],"correct":0},{"q":"Что получится, если поставить два ключа 木 mù («дерево») рядом?","options":["林 lín (лес)","明 míng (светлый)","好 hǎo (хорошо)"],"correct":0},{"q":"Иероглиф 人 rén относится к цельному (неделимому) типу.","tf":true}]}'),
  ('hsk0-32-numbers-basics', 1, 'fact', '{"emoji":"🖐️","title":"Считать до 99 можно зная всего 10 слов","text":"В китайском счёте нет исключений вроде «одиннадцать» или «сорок»: 11 — это буквально «десять-один» (十一 shíyī), а 23 — «два-десять-три» (二十三 èrshísān)."}'),
  ('hsk0-32-numbers-basics', 2, 'theory', '{"title":"Числа 1–10 и главные местоимения","blocks":[{"t":"table","head":["Знак","Пиньинь","Значение","Знак","Пиньинь","Значение"],"rows":[["一","yī","1","六","liù","6"],["二","èr","2","七","qī","7"],["三","sān","3","八","bā","8"],["四","sì","4","九","jiǔ","9"],["五","wǔ","5","十","shí","10"],["我","wǒ","я","他 / 她","tā","он / она"],["你","nǐ","ты","好","hǎo","хорошо"]]},{"t":"ex","zh":"你好！","py":"nǐ hǎo!","m":"Привет! / Здравствуйте!"},{"t":"ex","zh":"谢谢！","py":"xièxie!","m":"Спасибо!"},{"t":"ex","zh":"再见！","py":"zàijiàn!","m":"До свидания!"},{"t":"tip","text":"Обратите внимание: чисел 1–10 и местоимений более чем достаточно, чтобы уверенно стартовать в HSK 1!"}]}'),
  ('hsk0-32-numbers-basics', 3, 'game', '{"type":"emoji","big":true,"title":"Выберите правильное число","items":[{"emoji":"1️⃣","options":["一 yī","二 èr","十 shí"],"correct":0},{"emoji":"3️⃣","options":["二 èr","三 sān","五 wǔ"],"correct":1},{"emoji":"5️⃣","options":["四 sì","五 wǔ","八 bā"],"correct":1},{"emoji":"7️⃣","options":["七 qī","九 jiǔ","六 liù"],"correct":0},{"emoji":"🔟","options":["八 bā","九 jiǔ","十 shí"],"correct":2}]}'),
  ('hsk0-32-numbers-basics', 4, 'game', '{"type":"build","title":"Соберите числа и фразы","items":[{"target":"12 (十二 shí''èr)","answer":["十 shí","二 èr"],"hint":"Соберите число 12"},{"target":"20 (二十 èrshí)","answer":["二 èr","十 shí"],"hint":"Соберите число 20"},{"target":"25 (二十五 èrshíwǔ)","answer":["二 èr","十 shí","五 wǔ"],"hint":"Соберите число 25"},{"target":"你好 (nǐ hǎo)","answer":["你 nǐ","好 hǎo"],"hint":"Соберите «Здравствуйте!»"}]}'),
  ('hsk0-32-numbers-basics', 5, 'game', '{"type":"match","title":"Найдите пару","pairs":[["我 wǒ","я"],["你 nǐ","ты"],["他 tā","он"],["她 tā","она"],["谢谢 xièxie","спасибо"],["再见 zàijiàn","до свидания"]]}'),
  ('hsk0-32-numbers-basics', 6, 'quiz', '{"title":"Проверим","qs":[{"q":"Как по-китайски записывается число 11?","options":["十一 shíyī («десять-один»)","一十 yīshí","二一 èryī"],"correct":0},{"q":"Как по-китайски записывается число 30?","options":["三十 sānshí («три-десять»)","十三 shísān","三三 sānsān"],"correct":0},{"q":"Что означает местоимение 我 wǒ?","options":["я","ты","он"],"correct":0},{"q":"Что означает фраза 再见 zàijiàn?","options":["до свидания","спасибо","здравствуйте"],"correct":0},{"q":"Числа от 11 до 99 в китайском строятся по простой логике сложения и умножения десятков.","tf":true}]}'),
  ('hsk0-33-final-exam', 1, 'fact', '{"emoji":"🎓","title":"Финишная прямая HSK 0!","text":"Вы прошли все 9 разделов: от устройства слога и «букв-обманок» до тонов, орфографии, правил порядка черт и ключей. Пройдите итоговый зачёт и переходите к HSK 1!"}'),
  ('hsk0-33-final-exam', 2, 'game', '{"type":"listen","title":"Часть 1: Аудирование (тоны и согласные)","items":[{"say":"妈","options":["1-й тон (ˉ)","2-й тон (ˊ)","3-й тон (ˇ)","4-й тон (ˋ)"],"correct":0},{"say":"来","options":["1-й тон (ˉ)","2-й тон (ˊ)","3-й тон (ˇ)","4-й тон (ˋ)"],"correct":1},{"say":"马","options":["1-й тон (ˉ)","2-й тон (ˊ)","3-й тон (ˇ)","4-й тон (ˋ)"],"correct":2},{"say":"大","options":["1-й тон (ˉ)","2-й тон (ˊ)","3-й тон (ˇ)","4-й тон (ˋ)"],"correct":3},{"say":"七","options":["q","x","c","zh"],"correct":0},{"say":"西","options":["q","x","c","zh"],"correct":1},{"say":"这","options":["zh","z","ch","c"],"correct":0},{"say":"四","options":["s","sh","c","z"],"correct":0}]}'),
  ('hsk0-33-final-exam', 3, 'game', '{"type":"match","title":"Часть 2: Правила чтения и ключи","pairs":[["你好 nǐ hǎo","читаем ní hǎo (3+3 → 2+3)"],["不是 bú shì","不 перед 4-м тоном → 2-й"],["一个 yí gè","一 перед 4-м тоном → 2-й"],["去 qù","после q буква ü пишется без точек"],["女 nǚ","после n точки над ü сохраняются"],["氵","ключ «вода» (от 水 shuǐ)"]]}'),
  ('hsk0-33-final-exam', 4, 'quiz', '{"title":"Часть 3: Итоговый тест","qs":[{"q":"Как читается буква q в пиньине (七 qī)?","options":["Мягкое «чь» с выдохом","Как «к»","Как «ц»"],"correct":0},{"q":"Как на самом деле произносится приветствие 你好 nǐ hǎo?","options":["ní hǎo (2-й + 3-й тон)","nǐ hǎo (два 3-х тона)","nì hǎo (4-й + 3-й)"],"correct":0},{"q":"Где ставится знак тона в слоге hǎo?","options":["На букве a","На букве o","На букве h"],"correct":0},{"q":"Где ставится знак тона в слоге liù?","options":["На букве u (последней в iu)","На букве i","На букве l"],"correct":0},{"q":"Какую черту пишут первой в иероглифе 十 shí?","options":["Горизонталь 一 (横)","Вертикаль 丨 (竖)"],"correct":0},{"q":"Когда пишут нижнюю закрывающую черту рамки в знаке 日 rì?","options":["В самом конце, после заполнения середины","Самой первой","Второй"],"correct":0},{"q":"Какой ключ стоит слева в словах 河 hé («река») и 海 hǎi («море»)?","options":["氵 (вода)","亻 (человек)","讠 (речь)"],"correct":0},{"q":"Вы готовы к первому уроку HSK 1!","tf":true}]}'),
  ('hsk0-33-final-exam', 5, 'fact', '{"emoji":"🚀","title":"Поздравляем! Курс HSK 0 пройден","text":"Теперь пиньинь, тоны и иероглифы для вас — понятная система, а не загадка. Открывайте HSK 1 и начинайте строить первые диалоги!"}')
) as v(slug, pos, kind, payload)
join public.lessons l on l.slug = v.slug;

select l.slug, (select count(*) from public.lesson_slides s where s.lesson_id = l.id) as slides, (select count(*) from public.lesson_words w where w.lesson_id = l.id) as words from public.lessons l where l.slug in ('hsk0-01-how-to-study', 'hsk0-02-chinese-language', 'hsk0-03-writing-system', 'hsk0-04-syllable-structure', 'hsk0-05-trick-letters', 'hsk0-06-simple-vowels', 'hsk0-07-diphthongs', 'hsk0-08-i-u-v-finals', 'hsk0-09-nasal-finals', 'hsk0-10-bpmf', 'hsk0-11-dtnl', 'hsk0-12-gkh', 'hsk0-13-jqx', 'hsk0-14-zhchshr', 'hsk0-15-zcs', 'hsk0-16-four-tones', 'hsk0-17-neutral-tone', 'hsk0-18-tone-pairs-ear', 'hsk0-19-sandhi-third-tone', 'hsk0-20-sandhi-bu', 'hsk0-21-sandhi-yi', 'hsk0-22-spelling-yw', 'hsk0-23-spelling-v', 'hsk0-24-tone-placement', 'hsk0-25-eight-strokes', 'hsk0-26-stroke-order-rules', 'hsk0-27-writing-practice-1', 'hsk0-28-writing-practice-2', 'hsk0-29-radicals-basic', 'hsk0-30-radicals-chameleons', 'hsk0-31-character-structure', 'hsk0-32-numbers-basics', 'hsk0-33-final-exam') order by l.position;
